    int DeleteFile(const CWideString& path)
    {
        ++g_deletes;
        int i = Find(path.s);
        if (i < 0) return 1;
        --g_nFiles;
        if (i != g_nFiles) std::strcpy(g_files[i], g_files[g_nFiles]);
        return 0;
    }
